# prompts.py - picture prompts for titanic-cover (all gpt-image-2.5-sunburst, 1K, quality LOW, 1 variation, NO references)
# (The hero was generated with the CAP block '#2B4170 / #1C2B4F'; after measuring the hero the block became '#213C69 / #142744' for every later picture.)
# STYLE / CHARACTER / KEY / BG blocks word for word from memory/STYLE.md (the channel's locked look).
import json
CHAR = "Flat 2D cartoon: a simple white character with a big round head, a small soft body, noodle arms with simple four-finger hands and short legs with rounded feet, thick smooth black (#000000) outlines of even weight, about 2 % of the head width thick, flat white fill (#FEFDFD) with a very soft pale-grey shade (#EDEBEB) on the left side of the head and body, the round head is wider than the body and about 0.38 of the full body height, small solid black vertical oval eyes about one sixth of the head width tall, simple curved black eyebrows, no nose, no hair, no clothes, a pink tongue (#FC8D90) only when the mouth is open. Clean vector-like linework, flat colours, no texture, no text, no border."
CAP = " This character is an ocean explorer: exactly the same simple white character, wearing only a dark navy-blue knit watch cap with a folded-up brim (flat #213C69 with a darker #142744 folded brim, as measured on the hero) pulled onto the top of the round head - nothing else added, no hair, no clothes."
NAVY = " This character is a navy officer: exactly the same simple white character, wearing only a white naval officer's peaked cap with a black visor and a small gold badge on the front (flat white #FFFFFF crown with a pale grey #E3E6EA shade, black #1A1A1A visor, gold #F2C230 badge) sitting on top of the round head - nothing else added, no hair, no clothes."
OBJ = "Flat 2D cartoon in the same drawing style: bold clean thick smooth black outlines of even weight, flat colours with one simple soft shade, clean vector-like linework, simple shapes, no texture, no text, no letters, no numbers, no border, no characters."
def KEY(c='green'):
    col = 'pure green (#00FF00)' if c == 'green' else 'pure magenta (#FF00FF)'
    return f"Isolated on a perfectly flat, uniform, solid {col} background that fills the whole picture edge to edge: no shadow, no ground, no floor line, no gradient, no vignette, no border, no other objects. The whole subject in frame with a clear margin on every side."
BG = "Flat 2D cartoon background in the same drawing style: big simple flat-colour shapes, thick smooth black outlines only on the main shapes, no texture, no text, no labels, no arrows, no characters, calm and simple so a character reads clearly on top of it."
ROW3 = "Three DIFFERENT poses of the same character side by side in one row, all three the same size, with wide empty gaps between them, every copy full body, no ground drawn, bold clean thick outlines. "
BOOK = "a big closed hardcover book with a plain dark-red front cover (flat #B3312C with a darker #8C2420 spine, no title, no text, no picture on it)"
def tail(role, key='green'): return " Whole bodies in frame with a margin. " + CHAR + role + " " + KEY(key)

P = {
 'hero': ("2:3", "Full body, three-quarter view facing to the right, both hands held out in front of the chest with the open palms facing up, holding nothing, as if about to receive something, eyebrows raised, a small curious open mouth with the pink tongue showing. Whole body in frame with a margin. Bold clean thick outlines. " + CHAR + CAP + " " + KEY()),
 'hunter3': ("3:2", ROW3 + f"LEFT copy: three-quarter view facing to the RIGHT, holding {BOOK} upright in front of the chest with both hands, the front cover facing the viewer, the eyes looking sideways to the left, a sly closed-mouth grin, one eyebrow raised. MIDDLE copy: facing the viewer, worried: both hands clasped together under the chin, eyebrows tilted up in the middle, eyes wide, a small wavy mouth. RIGHT copy: three-quarter view facing to the RIGHT, a sudden idea: one index finger pointing straight up next to the head, eyes wide open, eyebrows raised high, a big open smile with the pink tongue showing." + tail(CAP)),
 'hunter3b': ("3:2", ROW3 + f"LEFT copy: facing the viewer, dozing off while standing: the head drooping forward and tilted to one side, both eyes closed as two short curved lines, the mouth a little open, both arms hanging loosely down. MIDDLE copy: facing the viewer, jumping for joy: both feet off the ground, both arms thrown straight up in the air with open hands, eyes squeezed shut happily, a huge open smile with the pink tongue showing. RIGHT copy: facing the viewer, proud: holding {BOOK} high above the head with both hands, the front cover facing the viewer, a big confident open smile, eyes closed happily." + tail(CAP)),
 'officer3': ("3:2", ROW3 + "LEFT copy: three-quarter view facing to the LEFT, handing something over: one arm stretched forward at chest height with the open palm facing up, holding nothing, the other hand behind the back, a serious face with lowered eyebrows. MIDDLE copy: three-quarter view facing to the LEFT, secretive: the index finger of one hand pressed against the closed mouth in a 'shh' gesture, eyes looking sideways to the left, eyebrows lowered. RIGHT copy: facing the viewer, embarrassed and nervous: one hand covering both eyes in a facepalm, the other hand on the hip, a wobbly worried mouth." + tail(NAVY)),
 'ship': ("3:2", "Side view of one chunky cartoon ocean research ship facing to the LEFT: a white hull (#F4F4F2 with a pale grey #D9DCE0 shade) with one dark-blue stripe (#2B4170) and a dark-red bottom part (#B3312C), the bottom of the hull is a flat horizontal line. A small white bridge cabin with three square windows near the LEFT front, one short mast with a small round radar dish on the cabin roof, and at the RIGHT back end a tall orange A-frame crane (#F28C28 with a darker #C96A14 shade) standing over the flat back deck with a big round cable drum under it. Short and chunky proportions, friendly simple shapes, no water, no people, no flags, no markings, no letters, no numbers. The whole ship in frame with a margin. " + OBJ + " " + KEY()),
 'sled_boiler': ("3:2", "Two separate objects side by side in one row with a wide empty gap between them, drawn at the same scale. LEFT: a boxy deep-sea robot camera sled: a rectangular open frame made of thick yellow tubes (#FFC72C with a darker #E0A21A shade), about twice as wide as it is tall, with a white rounded float block on top, two big round camera lenses (black glass with grey rims) side by side on its front face, two small round lamps, and a short thick black cable loop on top. RIGHT: a big old steam-ship boiler: a huge short fat iron cylinder seen from its round front end, dark rusty iron (#7A4A32 with a darker #5A3322 shade and a few orange rust patches #B5562A), three round furnace doors in a row on the round front face and a ring of round rivets around the edge. No faces, no text. " + OBJ + " " + KEY()),
 'sub': ("3:2", "One long old grey cartoon submarine broken into three separate pieces lying in one row with gaps between them, side view facing to the LEFT: LEFT the rounded front piece, MIDDLE a piece with the tall conning tower, RIGHT the tail piece with the propeller and two fins; every broken end is a jagged torn edge. Under the pieces a loose scatter of about eight small broken metal plates and bits. Dull grey metal (#6E7780 with a darker #4E565E shade) with a few rust streaks (#9C6A4A). No faces, no text, no numbers, no flags, no water. " + OBJ + " " + KEY()),
 'bow': ("3:2", "The front half of a huge old four-funnel steam liner from the early 1900s, broken off and resting on the sea floor, side view facing to the LEFT: the tall pointed bow with a long white railing along the top edge, two small anchor holes near the front, a near-black hull (#26282E with a darker #17181C shade) with a dark rusty red-brown lower part (#6B3A2A), two rows of small round portholes, long hanging rust drips like icicles (#A4532B) along the hull, one broken mast lying on the deck, the back end on the RIGHT broken off in a jagged torn edge. Big simple shapes. No funnels, no water, no ground, no fish, no people, no text, no letters, no names. " + OBJ + " " + KEY()),
 'night': ("2:3", "A calm open sea at night seen from the side, vertical picture. The top 58 % is a dark navy-blue night sky (#1B2550 at the top, #2E3B78 near the horizon) with small simple white star dots and a big pale yellow full moon (#F6E7A6) in the upper LEFT. The horizon is a flat straight line at 58 % of the height. Below it a calm dark-blue sea (#1E3A6E with a lighter #2C4F8A band near the horizon) with a few long flat lighter wave lines and a soft pale moon reflection. No ship, no land, no people, no text. " + BG),
}
json.dump(P, open('prompts.json', 'w'), indent=1)
with open('prompts.md', 'w') as f:
    f.write('# titanic-cover - picture prompts (all gpt-image-2.5-sunburst, 1K, quality LOW, 1 variation, no references)\n\n')
    for k, (ar, p) in P.items(): f.write(f'## {k} ({ar})\n{p}\n\n')
for k, (ar, p) in P.items(): print(k, ar, len(p))
